import sys
import requests
import xml.etree.ElementTree as ET
import json

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    zip_code = sys.argv[1]
    url = f"https://alerts.example.com/active?zip={zip_code}"

    try:
        response = requests.get(url)
        if response.status_code != 200:
            print("request failed", file=sys.stderr)
            sys.exit(1)
    except requests.RequestException:
        print("request failed", file=sys.stderr)
        sys.exit(1)

    try:
        root = ET.fromstring(response.text)
        alerts = []
        for alert in root.findall('alert'):
            alerts.append({
                'severity': alert.findtext('severity'),
                'headline': alert.findtext('headline'),
                'expires': alert.findtext('expires')
            })
    except ET.ParseError:
        sys.exit(0)

    with open(f"alerts_{zip_code}.json", "w") as f:
        json.dump(alerts, f)

if __name__ == "__main__":
    main()
